css:
.slide-deck { border: 1px solid var(--pds-border-subtle); border-radius: var(--pds-radius-md); background: var(--pds-slide-bg); color: var(--pds-slide-fg); overflow: hidden; margin: var(--pds-space-6) 0; outline: none; }
.slide-deck__controls { display: flex; align-items: center; gap: var(--pds-space-2); padding: var(--pds-space-2) var(--pds-space-3); background: var(--pds-slide-control-bg); color: var(--pds-slide-control-fg); }
.sd-prev, .sd-next, .sd-fullscreen { background: none; border: 1px solid rgba(255,255,255,0.4); color: var(--pds-slide-control-fg); cursor: pointer; padding: var(--pds-space-1) var(--pds-space-2); border-radius: var(--pds-radius-sm); font-size: var(--pds-text-sm); line-height: 1; }
.sd-prev:hover, .sd-next:hover, .sd-fullscreen:hover { background: rgba(255,255,255,0.15); }
.sd-prev[aria-disabled='true'], .sd-next[aria-disabled='true'] { opacity: 0.4; cursor: default; }
.sd-fullscreen { margin-left: auto; }
.sd-progress { font-size: var(--pds-text-sm); color: rgba(255,255,255,0.85); min-width: 4ch; text-align: center; }
.slide-deck__viewport { position: relative; aspect-ratio: var(--pds-slide-aspect); overflow: hidden; }
.slide { position: absolute; inset: 0; padding: var(--pds-space-8) var(--pds-space-10); overflow-y: auto; display: none; }
.slide.active { display: block; }
.slide h1, .slide h2 { font-size: 1.6em; margin-bottom: var(--pds-space-4); }
.slide p { font-size: 1.1em; line-height: 1.5; }
.slide-deck__transcript { border-top: 1px solid var(--pds-border-subtle); padding: var(--pds-space-3) var(--pds-space-4); font-size: var(--pds-text-sm); color: var(--pds-text-tertiary); }
.slide-deck__transcript summary { cursor: pointer; color: var(--pds-text-tertiary); }
.sd-fullscreen--active { position: fixed; inset: 0; z-index: 9999; border-radius: 0; background: #000; }
.sd-fullscreen--active .slide-deck__viewport { aspect-ratio: unset; height: calc(100% - 44px); }
